INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "朱高炽", "aliases": ["明仁宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明仁宗，永樂22年（1424年）八月，朱高炽即皇帝位。", "biography": null, "status": "draft", "id": "2dded14d-7183-56b5-9029-ca93826c1e80"}, {"name": "杨溥（明代内阁大学士）", "aliases": ["楊溥"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪熙元年（1425年）闰七月，杨溥以太常卿兼翰林学士身份共同处理内阁事务。", "biography": null, "status": "draft", "id": "1f1bfa42-5ca4-5450-84a8-f7927b05b3f7"}, {"name": "朱棣", "aliases": ["明成祖"], "era": "明", "birth_year": null, "death_year": null, "description": "明成祖，建文4年（1402年），朱棣即皇帝位。", "biography": null, "status": "draft", "id": "dd806a37-77e8-5244-96e9-4d71db81b600"}, {"name": "郑和", "aliases": ["鄭和"], "era": "明", "birth_year": null, "death_year": null, "description": "明代中官。本纪载其于永乐三年率舟师出使西洋各国。", "biography": null, "status": "draft", "id": "9a24d146-cea1-5746-85e4-479becda6195"}, {"name": "权谨", "aliases": ["權謹"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，洪熙元年（1425年）三月，权谨因孝行，由光禄丞升授文华殿大学士。", "biography": null, "status": "draft", "id": "bcf679c8-e27b-5c36-ac00-7e9bfca12063"}, {"name": "李安（明代安平伯）", "aliases": ["安平伯"], "era": "明", "birth_year": null, "death_year": null, "description": "李安（明代安平伯）与张辅同领左掖。", "biography": null, "status": "draft", "id": "351483eb-71df-5a0d-9ec4-d88888e27535"}, {"name": "杨士奇", "aliases": ["楊士奇"], "era": "明", "birth_year": null, "death_year": null, "description": "明代官员，建文4年（1402年）九月，杨士奇以翰林编修身份入直文渊阁。", "biography": null, "status": "draft", "id": "cf93d13f-f48a-5fc6-8687-47933c0ca559"}, {"name": "朱瞻基", "aliases": ["明宣宗"], "era": "明", "birth_year": null, "death_year": null, "description": "明宣宗，洪熙元年（1425年）六月，朱瞻基即皇帝位。", "biography": null, "status": "draft", "id": "888fc961-674c-52bf-b645-1351d5637434"}, {"name": "李时勉", "aliases": ["李懋"], "era": "明", "birth_year": null, "death_year": null, "description": "李时勉以侍读身份被下狱。", "biography": null, "status": "draft", "id": "c925d68f-aef6-5e23-93cb-cd7a19e52416"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明仁宗正月初一在奉天门受朝", "description": "洪熙元年正月初一，明仁宗朱高炽在奉天门接受朝见，当时没有奏乐。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月壬申朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "025eb33d-68fa-5fb6-8ddd-1f81112c9c26"}, {"title": "明仁宗命中央和地方官员尽责办事", "description": "洪熙元年正月乙亥，明仁宗朱高炽谕令中央、地方官员认真办好各自经管的事务。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月乙亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0bcdc8cf-180b-5af4-aa16-c067dddfe3ad"}, {"title": "明仁宗赴太庙祭祀", "description": "洪熙元年正月己卯，明仁宗朱高炽到太庙举行祭祀。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d45573c0-4088-5af6-9059-4f383650ba1a"}, {"title": "明廷设弘文阁，由杨溥主持", "description": "洪熙元年正月，明廷设立弘文阁，命儒臣入阁值勤，并令杨溥掌管阁中事务。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "929ee1ba-ea33-5679-ba08-baad28763fa0"}, {"title": "明仁宗因时雪未至，命大臣检点反省", "description": "洪熙元年正月癸未，因该降雪的时候没有降雪，明仁宗朱高炽命群臣检点反省。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cfc55e58-b26d-5b93-af96-b12a0d7c41ee"}, {"title": "明仁宗在南郊祭祀天地，以太祖、太宗配祭", "description": "洪熙元年正月丙戌，明仁宗朱高炽在南郊祭祀天地，奉明太祖和当时庙号太宗的朱棣配祭。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月丙戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8a0e82ea-4351-5fc5-a029-e28c157a5250"}, {"title": "明廷规定分等赏赐请假回乡省亲的朝臣", "description": "洪熙元年正月壬辰，朝廷规定，获准休假回乡探亲的朝臣可以得到不同等第的宝钞赏赐，并将做法定为法令。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a1b2ee09-e3a7-57bf-8424-2ffcc581d1b3"}, {"title": "周干、胡概、叶春奉命巡视南畿与浙江", "description": "洪熙元年正月己亥，朝廷命布政使周干、按察使胡概和参政叶春巡视南畿和浙江。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年正月己亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "33bb35ec-8fc0-5af5-bdb6-1a28680d5cd8"}, {"title": "明廷向边将颁发将军印", "description": "洪熙元年二月辛丑，朝廷向戍边将领颁发将军印。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年二月辛丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "82bb55c1-e3b7-52af-ab1b-aae56c1358b9"}, {"title": "明仁宗祭祀社稷", "description": "洪熙元年二月戊申，明仁宗朱高炽举行社稷祭祀。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年二月戊申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dc28af70-0ac5-55d5-b478-d6f86fe7c44d"}, {"title": "郑和奉命守备南京", "description": "洪熙元年二月，明廷命太监郑和负责南京守备。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "baca3faa-c915-5502-aa78-511b64f96187"}, {"title": "明仁宗举行耕耤礼", "description": "洪熙元年二月丙辰，明仁宗朱高炽按礼耕种耤田。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年二月丙辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cb34577f-b567-5375-a650-63ebf478433a"}, {"title": "朝廷将明太宗朱棣的神主入祀太庙", "description": "洪熙元年二月丙寅，朝廷将朱棣的神主入祀太庙，当时朱棣庙号太宗。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年二月丙寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0f5a961c-9711-537a-a4bc-a038540f5bbf"}, {"title": "南京多次发生地震", "description": "洪熙元年二月，南京多次发生地震。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3fe412e-3bc8-5cf9-b1e8-07a0b3297929"}, {"title": "权谨因孝行，由光禄丞升授文华殿大学士", "description": "洪熙元年（1425年）三月，权谨因孝行，由光禄丞升授文华殿大学士。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年（1425年）三月", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "2446d329-5ebf-581d-af68-cb28497f0cef"}, {"title": "明仁宗征求直言", "description": "洪熙元年三月丁丑，明仁宗朱高炽请臣下直陈政事。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5da6bcb1-12d3-51ba-abcf-26983b7b3953"}, {"title": "明仁宗命直接发放官麦救济隆平饥民", "description": "洪熙元年三月戊子，隆平发生饥荒，户部请求把公仓的麦子贷给百姓。明仁宗说，应直接发粮救济。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5c8663f0-9b1f-5a9b-be77-7cb6090ce79e"}, {"title": "明仁宗下诏依法定罪，扩大对刑罚的复核", "description": "洪熙元年三月己丑，明仁宗下诏，要求官员依法拟罪。如皇帝下令在法律之外用刑，司法官应反复上奏；五次未准，可与三公及大臣共同再奏。诏书还限制鞭背、宫刑和亲属连坐，并废除以诽谤立案治罪的禁令。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月己丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e773f133-12ea-51da-90c0-6c660cfc51d0"}, {"title": "薛禄受任镇朔大将军，巡防开平、大同", "description": "洪熙元年三月庚寅，朝廷任命阳武侯薛禄为镇朔大将军，率军巡防开平、大同一带边境。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b2f4c163-077c-5864-bd0f-aca44b398770"}, {"title": "李安与陈智奉命共同镇守交阯", "description": "洪熙元年三月辛卯，朝廷命参将安平伯李安与荣昌伯陈智共同镇守交阯。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b96fbef-edcc-5fcb-9554-1c25563f5ab2"}, {"title": "明仁宗准备还都南京，命北京官署恢复行在称谓", "description": "洪熙元年三月戊戌，明仁宗朱高炽准备还都南京，下诏命北京各官署改称行在，并恢复北京行部及行后军都督府。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月戊戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "41c445b6-c04e-5905-a7ca-7775efca334d"}, {"title": "南京多次发生地震", "description": "洪熙元年三月，南京多次发生地震。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "79038c05-967f-5ca2-86b7-9bc74b90e95b"}, {"title": "明仁宗命杨士奇当场起草赈灾减税诏书", "description": "洪熙元年四月壬寅，明仁宗得知山东和淮、徐百姓缺粮，当地仍在急征夏税，便召杨士奇拟诏，免当年夏税及一半秋粮。杨士奇提出先通知户部和工部，朱高炽认为救急不能拖延，命他立即写好诏书，当场用印颁行。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月壬寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6192a68f-af43-5c47-9d37-53d921083958"}, {"title": "明廷设置北京行都察院", "description": "洪熙元年四月，朝廷设置北京行都察院。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "762bea7f-f5f9-559f-8a6f-437028f4997d"}, {"title": "皇太子朱瞻基奉命拜谒孝陵并留守南京", "description": "洪熙元年四月壬子，明仁宗命皇太子朱瞻基前往孝陵拜谒，随后留守南京。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5bb717a-17d6-556f-ab98-4cc0d4a37e54"}, {"title": "明仁宗到天寿山拜谒长陵", "description": "洪熙元年四月戊午，明仁宗朱高炽到天寿山拜谒长陵。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月戊午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ad2b5b53-fbf0-50a7-afe9-9007e6376d2d"}, {"title": "明仁宗拜谒长陵后返回宫中", "description": "洪熙元年四月己未，明仁宗朱高炽返回宫中。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e451c926-f8b2-59c7-ae3a-2d383261f648"}, {"title": "明廷救济河南和大名饥民", "description": "洪熙元年四月，明廷赈济河南和大名的饥民。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "76156a99-9f29-53d9-8887-f9bee4ee3753"}, {"title": "南京多次发生地震", "description": "洪熙元年四月，南京多次发生地震。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "83152c1e-d4c7-515d-8249-144d2a86ca51"}, {"title": "李时勉、罗汝敬因上言改任御史，随后被下狱", "description": "洪熙元年五月己卯，侍读李时勉和侍讲罗汝敬因上言政事，改任御史，随后被下狱。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年五月己卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a54b0c3f-6bc9-5e9e-ac68-4cd1d91570ab"}, {"title": "明仁宗患病，派人召在南京的皇太子", "description": "洪熙元年五月庚辰，明仁宗朱高炽身体不适，派使者到南京召皇太子朱瞻基。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年五月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "41843872-9123-5419-a504-17e344300beb"}, {"title": "明仁宗病重，遗诏传位皇太子", "description": "洪熙元年五月辛巳，明仁宗朱高炽病势转重，留下遗诏，将皇位传给皇太子朱瞻基。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年五月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00f6441f-7623-5170-983e-662616171ca6"}, {"title": "明仁宗朱高炽在钦安殿去世", "description": "洪熙元年五月辛巳，明仁宗朱高炽在钦安殿去世，本纪记享年四十八。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年五月辛巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a6dd1ead-450d-566a-a4db-f22a3d34d0f6"}, {"title": "朱高炽被上尊谥，庙号仁宗", "description": "洪熙元年七月己巳，明廷为朱高炽上尊谥，定庙号为仁宗。本纪随后记他安葬在献陵。", "start_year": 1425, "end_year": 1425, "time_original": "洪熙元年七月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "73a8578f-0f84-5280-819e-4fa327f9713d"}, {"title": "黎利进攻清化，都指挥同知陈忠阵亡", "description": "永乐二十二年九月丁亥，黎利率部进攻清化，都指挥同知陈忠在交战中身亡。卷末校记说明，官职原脱「都」字。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年九月丁亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3b71b373-5938-5631-9116-fd9dc39b075f"}, {"title": "明廷增加京官与军士的每月俸粮", "description": "永乐二十二年十月庚申，明廷增加京官和军士每月领取的俸粮。卷末校记记载，旧文误作当月已经出现的丁巳。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十月庚申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "75cf3689-993d-5dee-9cff-a2900cd86836"}, {"title": "明仁宗宽免建文诸臣被罚全家戍边的外亲", "description": "永乐二十二年十二月癸卯，明廷宽免因建文诸臣获罪而全家被罚戍边的外亲。每家留一人继续戍守，其余释放回乡。卷末校记说明，此处为「外亲」。", "start_year": 1424, "end_year": 1424, "time_original": "永乐二十二年十二月癸卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "3ce3e113-8a68-5161-866b-e749aafce462"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

